#[test]
fn encrypted_pdfs_need_a_password() {
    let bytes = sample_pdf_encrypted(2, "owner", "secret");
    assert!(matches!(
        Pdf::from_bytes(&bytes, None),
        Err(Error::Encrypted)
    ));
    assert!(matches!(
        Pdf::from_bytes(&bytes, Some("nope")),
        Err(Error::WrongPassword)
    ));
    let mut pdf = Pdf::from_bytes(&bytes, Some("secret")).unwrap();
    assert!(pdf.was_encrypted());
    assert_eq!(pdf.page_count(), 2);
    // The result is written without encryption.
    let out = pdf.to_bytes().unwrap();
    let reopened = Pdf::from_bytes(&out, None).unwrap();
    assert!(content_text(&reopened, 1).contains("Page 1"));

    let i = info(&bytes, None).unwrap();
    assert!(i.encrypted);
    assert!(!i.readable);
    let i = info(&bytes, Some("secret")).unwrap();
    assert!(i.encrypted && i.readable);
    assert_eq!(i.pages.len(), 2);
    assert_eq!(i.title.as_deref(), Some("Sample"));
}

#[test]
fn encrypted_with_empty_user_password_still_needs_the_flag() {
    let bytes = sample_pdf_encrypted(1, "owner", "");
    assert!(matches!(
        Pdf::from_bytes(&bytes, None),
        Err(Error::Encrypted)
    ));
    assert_eq!(Pdf::from_bytes(&bytes, Some("")).unwrap().page_count(), 1);
    let i = info(&bytes, None).unwrap();
    assert!(i.encrypted && i.readable);
}

#[test]
fn watermark_stamps_selected_pages() {
    let mut pdf = open(&sample_pdf(3));
    let opts = WatermarkOptions {
        text: "DRAFT".into(),
        ..Default::default()
    };
    assert_eq!(add_watermark(&mut pdf, &opts, &ranges("1,3")).unwrap(), 2);
    let bytes = pdf.to_bytes().unwrap();
    let pdf = open(&bytes);
    let p1 = content_text(&pdf, 1);
    assert!(p1.contains("(DRAFT) Tj"), "{p1}");
    assert!(p1.contains("Page 1"), "original content kept");
    assert!(!content_text(&pdf, 2).contains("DRAFT"));
    // Opacity goes through an ExtGState.
    let doc = pdf.document();
    let page = doc.get_dictionary(doc.get_pages()[&1]).unwrap();
    let res = page.get(b"Resources").unwrap().as_dict().unwrap();
    let gs = res.get(b"ExtGState").unwrap().as_dict().unwrap();
    let (_, gs_ref) = gs.iter().next().unwrap();
    let gs = doc.get_dictionary(gs_ref.as_reference().unwrap()).unwrap();
    assert_eq!(gs.get(b"ca").unwrap().as_float().unwrap(), 0.3);
    // The original font name is still there next to ours.
    assert!(res.get(b"Font").unwrap().as_dict().unwrap().has(b"F1"));
}

#[test]
fn watermark_checks_its_options() {
    let mut pdf = open(&sample_pdf(1));
    let all = PageRanges::all();
    let e = add_watermark(&mut pdf, &WatermarkOptions::default(), &all).unwrap_err();
    assert!(e.to_string().contains("empty"));
    let opts = WatermarkOptions {
        text: "日本".into(),
        ..Default::default()
    };
    assert!(
        add_watermark(&mut pdf, &opts, &all)
            .unwrap_err()
            .to_string()
            .contains("Latin")
    );
    let opts = WatermarkOptions {
        text: "x".into(),
        opacity: 2.0,
        ..Default::default()
    };
    assert!(add_watermark(&mut pdf, &opts, &all).is_err());
    // Latin-1 and typographic quotes are fine.
    let opts = WatermarkOptions {
        text: "Rahasia — “Draf” é".into(),
        ..Default::default()
    };
    add_watermark(&mut pdf, &opts, &all).unwrap();
}

#[test]
fn watermark_twice_keeps_graphics_state_balanced() {
    let mut pdf = open(&sample_pdf(1));
    let opts = WatermarkOptions {
        text: "A".into(),
        ..Default::default()
    };
    add_watermark(&mut pdf, &opts, &PageRanges::all()).unwrap();
    add_watermark(&mut pdf, &opts, &PageRanges::all()).unwrap();
    let text = content_text(&pdf, 1);
    let q = text.split_whitespace().filter(|t| *t == "q").count();
    let big_q = text.split_whitespace().filter(|t| *t == "Q").count();
    assert_eq!(q, big_q, "{text}");
    assert_eq!(text.matches("(A) Tj").count(), 2);
}

/// The Tm translation of the first stamp on page `p`.
fn stamp_origin(pdf: &Pdf, p: u32) -> (f32, f32) {
    let text = content_text(pdf, p);
    let tokens: Vec<&str> = text.split_whitespace().collect();
    let i = tokens.iter().position(|t| *t == "Tm").unwrap();
    (
        tokens[i - 2].parse().unwrap(),
        tokens[i - 1].parse().unwrap(),
    )
}

#[test]
fn page_numbers_follow_format_and_start() {
    let mut pdf = open(&sample_pdf(4));
    let opts = PageNumberOptions {
        format: "{n} of {total}".into(),
        start: 1,
        ..Default::default()
    };
    assert_eq!(add_page_numbers(&mut pdf, &opts, &ranges("2-")).unwrap(), 3);
    let bytes = pdf.to_bytes().unwrap();
    let pdf = open(&bytes);
    assert!(!content_text(&pdf, 1).contains(" of "));
    assert!(content_text(&pdf, 2).contains("(1 of 3) Tj"));
    assert!(content_text(&pdf, 4).contains("(3 of 3) Tj"));
}

#[test]
fn page_number_is_centred_at_the_bottom() {
    let mut pdf = open(&sample_pdf(1));
    add_page_numbers(&mut pdf, &PageNumberOptions::default(), &PageRanges::all()).unwrap();
    let (x, y) = stamp_origin(&pdf, 1);
    let w = crate::overlay::text_width("1", 12.0);
    assert!((x - (sample_width(1) - w) / 2.0).abs() < 0.01, "x {x}");
    assert!((y - 30.0).abs() < 0.01, "y {y}");
}

#[test]
fn page_number_positions_and_format_errors() {
    let mut pdf = open(&sample_pdf(1));
    let opts = PageNumberOptions {
        position: "top-right".parse().unwrap(),
        ..Default::default()
    };
    add_page_numbers(&mut pdf, &opts, &PageRanges::all()).unwrap();
    let (x, y) = stamp_origin(&pdf, 1);
    let w = crate::overlay::text_width("1", 12.0);
    assert!((x - (sample_width(1) - 30.0 - w)).abs() < 0.01, "x {x}");
    assert!((y - (800.0 - 30.0 - 12.0 * 0.718)).abs() < 0.01, "y {y}");

    let bad = PageNumberOptions {
        format: "page".into(),
        ..Default::default()
    };
    assert!(add_page_numbers(&mut pdf, &bad, &PageRanges::all()).is_err());
    assert!("sideways".parse::<Position>().is_err());
    assert_eq!(
        "BottomLeft".parse::<Position>().unwrap(),
        Position::BottomLeft
    );
}

#[test]
fn page_numbers_on_rotated_pages_use_the_displayed_bottom() {
    // Page width 601, height 800, /Rotate 90: displayed 800 wide, 601 tall.
    let mut pdf = open(&sample_pdf_inherited(1));
    add_page_numbers(&mut pdf, &PageNumberOptions::default(), &PageRanges::all()).unwrap();
    let text = content_text(&pdf, 1);
    assert!(text.contains("0.0 1.0 -1.0 0.0 601.0 0.0 cm"), "{text}");
    let (x, y) = stamp_origin(&pdf, 1);
    let w = crate::overlay::text_width("1", 12.0);
    assert!((x - (800.0 - w) / 2.0).abs() < 0.01, "x {x}");
    assert!((y - 30.0).abs() < 0.01);
}

#[test]
fn images_become_pages() {
    let images = vec![
        ("a.png".to_string(), sample_png(40, 20, false)),
        ("b.jpg".to_string(), sample_jpeg(30, 60)),
        ("c.png".to_string(), sample_png(10, 10, true)),
    ];
    let mut pdf = images_to_pdf(&images, &ImageOptions::default()).unwrap();
    let bytes = pdf.to_bytes().unwrap();
    let i = info(&bytes, None).unwrap();
    let sizes: Vec<(f32, f32)> = i.pages.iter().map(|p| (p.width, p.height)).collect();
    assert_eq!(sizes, [(40.0, 20.0), (30.0, 60.0), (10.0, 10.0)]);
    let pdf = open(&bytes);
    let doc = pdf.document();
    let mut filters = Vec::new();
    let mut smasks = 0;
    for obj in doc.objects.values() {
        if let Ok(s) = obj.as_stream()
            && s.dict.get(b"Subtype").and_then(|o| o.as_name()).ok() == Some(b"Image".as_slice())
        {
            filters.push(s.dict.get(b"Filter").unwrap().as_name().unwrap().to_vec());
            if s.dict.has(b"SMask") {
                smasks += 1;
            }
        }
    }
    // The JPEG is embedded as is; PNGs (and the alpha mask) use Flate.
    assert!(filters.contains(&b"DCTDecode".to_vec()));
    assert_eq!(
        filters
            .iter()
            .filter(|f| f.as_slice() == b"FlateDecode")
            .count(),
        3
    );
    assert_eq!(smasks, 1);
}

#[test]
fn images_on_a4_with_margins_fit_and_turn() {
    let images = vec![
        ("wide.png".to_string(), sample_png(400, 100, false)),
        ("tall.png".to_string(), sample_png(100, 400, false)),
    ];
    let opts = ImageOptions {
        page_size: PageSize::A4,
        orientation: Orientation::Auto,
        margin: 36.0,
    };
    let mut pdf = images_to_pdf(&images, &opts).unwrap();
    let bytes = pdf.to_bytes().unwrap();
    let i = info(&bytes, None).unwrap();
    assert!(
        i.pages[0].width > i.pages[0].height,
        "wide image → landscape"
    );
    assert_eq!(i.pages[1].paper_name().as_deref(), Some("A4"));
    // The tall image is scaled to the printable height and centred.
    let text = content_text(&open(&bytes), 2);
    let ah = 841.89 - 72.0;
    let aw = ah / 4.0;
    let expect = format!(
        "{} 0 0 {} {} 36 cm",
        aw,
        ah,
        36.0 + (595.276 - 72.0 - aw) / 2.0
    );
    let got: Vec<f32> = text
        .split_whitespace()
        .take_while(|t| *t != "cm")
        .filter_map(|t| t.parse().ok())
        .collect();
    let want: Vec<f32> = expect
        .split_whitespace()
        .filter_map(|t| t.parse().ok())
        .collect();
    for (g, w) in got.iter().zip(&want) {
        assert!((g - w).abs() < 0.01, "{text} vs {expect}");
    }
}

#[test]
fn images_reject_other_formats_and_bad_margins() {
    let gif = b"GIF89a\x01\x00\x01\x00".to_vec();
    let e = images_to_pdf(&[("x.gif".into(), gif)], &ImageOptions::default()).unwrap_err();
    assert!(e.to_string().contains("x.gif"), "{e}");
    let opts = ImageOptions {
        page_size: PageSize::A4,
        margin: 400.0,
        ..Default::default()
    };
    let e = images_to_pdf(&[("a.png".into(), sample_png(4, 4, false))], &opts).unwrap_err();
    assert!(e.to_string().contains("no room"), "{e}");
    assert!(images_to_pdf(&[], &ImageOptions::default()).is_err());
}

#[test]
fn exif_matrices_map_the_unit_square_upright() {
    // Where the stored image's top-left pixel (u=0, v=1) lands.
    let top_left = |m: [f32; 6]| (m[2] + m[4], m[3] + m[5]);
    let im = crate::images::exif_matrix;
    assert_eq!(top_left(im(1)), (0.0, 1.0));
    assert_eq!(top_left(im(3)), (1.0, 0.0));
    // Orientation 6 is "rotate 90° clockwise to view": top-left goes top-right.
    assert_eq!(top_left(im(6)), (1.0, 1.0));
    assert_eq!(top_left(im(8)), (0.0, 0.0));
}

#[test]
fn compress_merges_duplicates_and_shrinks() {
    // Merging a file with itself duplicates every font and content stream.
    let mut merged = merge(open(&sample_pdf(20)), vec![open(&sample_pdf(20))]).unwrap();
    let original = merged.to_bytes().unwrap();
    let pdf = open(&original);
    let (out, report) = compress(pdf, &original).unwrap();
    assert!(report.duplicates_merged >= 20, "{report:?}");
    assert!(!report.kept_original);
    assert!(report.after < report.before, "{report:?}");
    assert_eq!(out.len(), report.after);
    let mut again = open(&out);
    assert_eq!(again.page_count(), 40);
    assert_eq!(order(&mut again)[..3], [1, 2, 3]);
}

#[test]
fn compress_keeps_the_original_when_it_cannot_win() {
    let mut merged = merge(open(&sample_pdf(3)), vec![]).unwrap();
    let original = merged.to_bytes().unwrap();
    let (once, _) = compress(open(&original), &original).unwrap();
    let (twice, report) = compress(open(&once), &once).unwrap();
    assert!(report.kept_original, "{report:?}");
    assert_eq!(twice, once);
}

#[test]
fn compress_report_percent() {
    let r = CompressReport {
        before: 200,
        after: 150,
        unused_removed: 0,
        duplicates_merged: 0,
        kept_original: false,
    };
    assert_eq!(r.saved_percent(), 25.0);
}

// ── assembling edited documents ──────────────────────────────────────────

fn pick(source: usize, page: u32, turn: i64) -> Pick {
    Pick { source, page, turn }
}

#[test]
fn assemble_reorders_rotates_and_duplicates() {
    let base = open(&sample_pdf(4));
    let picks = [
        pick(0, 2, 0),
        pick(0, 0, 0),
        pick(0, 0, 90),
        pick(0, 3, -90),
    ];
    let mut out = assemble(vec![base], &picks).unwrap();
    assert_eq!(layout(&mut out), [(3, 0), (1, 0), (1, 90), (4, 270)]);
    // Page 2 is gone from the file.
    let text: String = (1..=4).map(|p| content_text(&out, p)).collect();
    assert!(!text.contains("Page 2"), "{text}");
    assert_eq!(
        info(&out.to_bytes().unwrap(), None)
            .unwrap()
            .title
            .as_deref(),
        Some("Sample")
    );
}

#[test]
fn assemble_adds_rotation_to_inherited_rotation() {
    let base = open(&sample_pdf_inherited(2));
    let mut out = assemble(vec![base], &[pick(0, 1, 90), pick(0, 0, 0)]).unwrap();
    assert_eq!(layout(&mut out), [(2, 180), (1, 90)]);
}

#[test]
fn assemble_inserts_pages_of_other_pdfs() {
    let base = open(&sample_pdf(3));
    let other = open(&sample_pdf(2));
    let blank = blank_page(300.0, 400.0);
    let picks = [
        pick(0, 0, 0),
        pick(1, 1, 0),
        pick(2, 0, 0),
        pick(0, 1, 0),
        pick(0, 2, 0),
    ];
    let mut out = assemble(vec![base, other, blank], &picks).unwrap();
    let bytes = out.to_bytes_compact().unwrap();
    assert!(qpdf_ok(&bytes));
    let i = info(&bytes, None).unwrap();
    let widths: Vec<f32> = i.pages.iter().map(|p| p.width).collect();
    assert_eq!(widths, [601.0, 602.0, 300.0, 602.0, 603.0]);
    assert_eq!(page_size(&out, 2), Some((300.0, 400.0)));
    // The pages of the other file came with their contents.
    assert!(content_text(&out, 2).contains("Page 2"));
    let reopened = open(&bytes);
    assert_eq!(reopened.page_count(), 5);
}

#[test]
fn assemble_checks_its_picks() {
    let e = assemble(vec![open(&sample_pdf(2))], &[pick(0, 5, 0)]).unwrap_err();
    assert!(e.to_string().contains("out of range"), "{e}");
    let e = assemble(vec![open(&sample_pdf(2))], &[pick(0, 0, 45)]).unwrap_err();
    assert!(e.to_string().contains("multiple of 90"), "{e}");
    let e = assemble(vec![open(&sample_pdf(2))], &[]).unwrap_err();
    assert!(e.to_string().contains("at least one page"), "{e}");
}

/// Bookmark titles, depth-first, with their nesting depth.
fn bookmarks(pdf: &Pdf) -> Vec<(usize, String)> {
    fn walk(
        doc: &lopdf::Document,
        node: lopdf::ObjectId,
        depth: usize,
        out: &mut Vec<(usize, String)>,
    ) {
        let mut next = doc
            .get_dictionary(node)
            .ok()
            .and_then(|d| d.get(b"First").ok())
            .and_then(|o| o.as_reference().ok());
        while let Some(id) = next {
            let d = doc.get_dictionary(id).unwrap();
            let title = d.get(b"Title").and_then(|t| t.as_str()).unwrap_or(b"");
            out.push((depth, String::from_utf8_lossy(title).into_owned()));
            walk(doc, id, depth + 1, out);
            next = d.get(b"Next").ok().and_then(|o| o.as_reference().ok());
        }
    }
    let doc = pdf.document();
    let mut out = Vec::new();
    if let Ok(root) = doc
        .catalog()
        .unwrap()
        .get(b"Outlines")
        .and_then(|o| o.as_reference())
    {
        walk(doc, root, 0, &mut out);
    }
    out
}

fn link_count(pdf: &Pdf, page: u32) -> usize {
    let doc = pdf.document();
    let id = doc.get_pages()[&page];
    doc.get_dictionary(id)
        .unwrap()
        .get(b"Annots")
        .and_then(|a| a.as_array())
        .map_or(0, |a| a.len())
}

#[test]
fn deleting_pages_drops_dead_bookmarks_and_links() {
    let base = open(&sample_pdf_linked(4));
    assert_eq!(bookmarks(&base).len(), 5);
    // Page 4 goes; page 2 moves first.
    let mut out = assemble(vec![base], &[pick(0, 1, 0), pick(0, 0, 0), pick(0, 2, 0)]).unwrap();
    let bytes = out.to_bytes().unwrap();
    let out = open(&bytes);
    // "Page 4" had a child, so it stays as a heading without a target.
    assert_eq!(
        bookmarks(&out),
        [
            (0, "Page 1".into()),
            (0, "Page 2".into()),
            (0, "Page 3".into()),
            (0, "Page 4".into()),
            (1, "Back to start".into()),
        ]
    );
    // Both links led to page 4 (one by name): gone, with the open action.
    assert_eq!(link_count(&out, 1), 0);
    assert_eq!(link_count(&out, 2), 0);
    assert!(
        out.document()
            .catalog()
            .unwrap()
            .get(b"OpenAction")
            .is_err()
    );
    assert!(qpdf_ok(&bytes));
}

#[test]
fn kept_targets_follow_their_pages() {
    let base = open(&sample_pdf_linked(3));
    // Page 1 goes: its bookmark goes; the other bookmarks and links stay.
    let mut out = assemble(vec![base], &[pick(0, 2, 0), pick(0, 1, 0)]).unwrap();
    let out = open(&out.to_bytes().unwrap());
    let titles: Vec<String> = bookmarks(&out).into_iter().map(|(_, t)| t).collect();
    // "Back to start" pointed at page 1: gone too.
    assert_eq!(titles, ["Page 2", "Page 3"]);
    // Page 2's named link to the last page stays (page 2 is now second).
    assert_eq!(link_count(&out, 2), 1);
    let root = out.document().catalog().unwrap();
    let outlines = out
        .document()
        .get_dictionary(root.get(b"Outlines").unwrap().as_reference().unwrap())
        .unwrap();
    assert_eq!(outlines.get(b"Count").unwrap().as_i64().unwrap(), 2);
}

#[test]
fn delete_tool_also_drops_dead_bookmarks() {
    let mut pdf = open(&sample_pdf_linked(3));
    delete(&mut pdf, &ranges("3")).unwrap();
    let titles: Vec<String> = bookmarks(&pdf).into_iter().map(|(_, t)| t).collect();
    assert_eq!(titles, ["Page 1", "Page 2", "Page 3", "Back to start"]);
    assert_eq!(link_count(&pdf, 1), 0);
}

#[test]
fn saving_keeps_the_password_protection() {
    let bytes = sample_pdf_encrypted(3, "owner", "user");
    let base = Pdf::from_bytes(&bytes, Some("user")).unwrap();
    let mut out = assemble(vec![base], &[pick(0, 2, 0), pick(0, 0, 90)]).unwrap();
    let saved = out.to_bytes_encrypted(true).unwrap();
    assert!(matches!(
        Pdf::from_bytes(&saved, None),
        Err(Error::Encrypted)
    ));
    let mut again = Pdf::from_bytes(&saved, Some("user")).unwrap();
    assert!(again.was_encrypted());
    assert!(content_text(&again, 1).contains("Page 3"));
    assert_eq!(layout(&mut again), [(3, 0), (1, 90)]);
    // The owner password still works too, and the in-memory copy stays readable.
    assert!(Pdf::from_bytes(&saved, Some("owner")).is_ok());
    assert!(content_text(&out, 1).contains("Page 3"));
    assert!(qpdf_ok_with(&saved, Some("user")));
    // Without keeping it, the result opens without a password.
    let plain = out.to_bytes_encrypted(false).unwrap();
    assert!(Pdf::from_bytes(&plain, None).is_ok());
    assert!(qpdf_ok(&plain));
}

#[test]
fn write_atomic_replaces_the_file() {
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("a.pdf");
    std::fs::write(&path, b"old").unwrap();
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt as _;
        std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o640)).unwrap();
    }
    write_atomic(&path, b"new").unwrap();
    assert_eq!(std::fs::read(&path).unwrap(), b"new");
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt as _;
        let mode = std::fs::metadata(&path).unwrap().permissions().mode();
        assert_eq!(mode & 0o777, 0o640);
    }
    // No temporary file is left behind.
    assert_eq!(std::fs::read_dir(dir.path()).unwrap().count(), 1);
}

#[test]
fn duplicated_pages_get_their_own_annotations() {
    let base = open(&sample_pdf_linked(2));
    let mut out = assemble(vec![base], &[pick(0, 0, 0), pick(0, 0, 0), pick(0, 1, 0)]).unwrap();
    let bytes = out.to_bytes().unwrap();
    let out = open(&bytes);
    let doc = out.document();
    let pages = doc.get_pages();
    let annot = |p: u32| {
        doc.get_dictionary(pages[&p])
            .unwrap()
            .get(b"Annots")
            .unwrap()
            .as_array()
            .unwrap()[0]
            .as_reference()
            .unwrap()
    };
    assert_ne!(annot(1), annot(2));
    let p = |a| {
        doc.get_dictionary(a)
            .unwrap()
            .get(b"P")
            .ok()
            .and_then(|o| o.as_reference().ok())
    };
    assert_eq!(p(annot(2)), Some(pages[&2]));
    assert!(qpdf_ok(&bytes));
}

/// `qpdf --check` passes (skipped when qpdf isn't installed).
fn qpdf_ok(bytes: &[u8]) -> bool {
    qpdf_ok_with(bytes, None)
}

fn qpdf_ok_with(bytes: &[u8], password: Option<&str>) -> bool {
    let Ok(dir) = tempfile::tempdir() else {
        return true;
    };
    let path = dir.path().join("check.pdf");
    std::fs::write(&path, bytes).unwrap();
    let mut cmd = std::process::Command::new("qpdf");
    if let Some(p) = password {
        cmd.arg(format!("--password={p}"));
    }
    match cmd.arg("--check").arg(&path).output() {
        Ok(out) => {
            if !out.status.success() {
                eprintln!(
                    "qpdf: {}{}",
                    String::from_utf8_lossy(&out.stdout),
                    String::from_utf8_lossy(&out.stderr)
                );
            }
            out.status.success()
        }
        Err(_) => true,
    }
}

/// AES-256 files (made by qpdf, when it is installed) keep their protection.
#[test]
fn saving_keeps_aes_256_protection() {
    let dir = tempfile::tempdir().unwrap();
    let plain = dir.path().join("plain.pdf");
    let locked = dir.path().join("locked.pdf");
    std::fs::write(&plain, sample_pdf(3)).unwrap();
    let made = std::process::Command::new("qpdf")
        .args(["--encrypt", "user", "owner", "256", "--"])
        .arg(&plain)
        .arg(&locked)
        .status();
    if !made.is_ok_and(|s| s.success()) {
        eprintln!("qpdf not available: skipped");
        return;
    }
    let bytes = std::fs::read(&locked).unwrap();
    let base = Pdf::from_bytes(&bytes, Some("user")).unwrap();
    let mut out = assemble(vec![base], &[pick(0, 1, 0), pick(0, 0, 180)]).unwrap();
    let saved = out.to_bytes_encrypted(true).unwrap();
    assert!(matches!(
        Pdf::from_bytes(&saved, None),
        Err(Error::Encrypted)
    ));
    let mut again = Pdf::from_bytes(&saved, Some("user")).unwrap();
    assert_eq!(layout(&mut again), [(2, 0), (1, 180)]);
    assert!(qpdf_ok_with(&saved, Some("user")));
}
